export default VERIFIED

/** Site/spawn/callout names for a map, or null if that map has no footage yet. */
export function verifiedFor(mapId) {
  return VERIFIED[mapId] || null
}

/** True when this exact name was actually read off the screen for this map. */
export function isVerifiedName(mapId, name) {
  const v = VERIFIED[mapId]
  if (!v || !name) return false
  const k = String(name).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
  return [...v.sites, ...v.spawns, ...v.callouts].some((e) => {
    const n = e.name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
    return n === k || n.includes(k) || k.includes(n)
  })
}
